interface SceneObject{id:string;type:'box'|'sphere'|'cylinder'|'plane'|'figure'|'camera';position:Vec3;rotation:Vec3;scale:Vec3;color?:string;figurePose?:string;figureSrc?:string;figureFmt?:string;}
type Vec3=[number,number,number];type GizmoMode='translate'|'rotate'|'scale';type TrackType='dolly'|'curved'|'orbit';interface SpeedKey{time:number;speed:number;}interface RotationKey{time:number;pitch:number;yaw:number;}interface AnimTrack{modelId:string;start:number;dur:number;color:string;}
