const SHARED_MAT=new THREE.MeshStandardMaterial({color:'#aaaaaa',roughness:0.35,metalness:0.25});
function standardize(child:any){if(child.isMesh){child.material=SHARED_MAT;}}function mergeGroupMeshes(g:THREE.Group){const byMat=new Map<string,{mat:THREE.Material;geoms:THREE.BufferGeometry[]}>();g.traverse((ch:any)=>{if(ch.isMesh&&ch.geometry){const k=ch.material.uuid;if(!byMat.has(k))byMat.set(k,{mat:ch.material,geoms:[]});byMat.get(k)!.geoms.push(ch.geometry.clone());}});if(byMat.size===0)return;g.clear();for(const[,v]of byMat){if(v.geoms.length>1){const mg=mergeGeometries(v.geoms,false);g.add(new THREE.Mesh(mg,v.mat));}else{g.add(new THREE.Mesh(v.geoms[0],v.mat));}}}
function normalizeScale(group:THREE.Group){const box=new THREE.Box3().setFromObject(group);const size=box.getSize(new THREE.Vector3());const maxDim=Math.max(size.x,size.y,size.z);if(maxDim>3){const s=3/maxDim;group.scale.setScalar(s);group.position.y+=box.min.y*s*-1;}}
function SafeModel({poseId,figureSrc,fallback,objId,noAnim,figureFmt}:{poseId:string;figureSrc?:string;fallback:React.ReactNode;objId?:string;noAnim?:boolean;figureFmt?:string}){const src=figureSrc||(poseRegistry.get(poseId)?.src);const[exists,setExists]=useState<boolean|string>('loading');useEffect(()=>{if(!src){setExists(false);return;}if(src.startsWith('data:')||src.startsWith('blob:')){setExists(src);return;}let c=false;fetch(src,{method:'HEAD'}).then(r=>{if(!c)setExists(r.ok?src:false);}).catch(()=>{if(!c)setExists(false);});return()=>{c=true;};},[src]);if(exists==='loading')return null;if(!exists||typeof exists!=='string')return<>{fallback}</>;const isFBX=figureFmt==='fbx'||exists.toString().includes('S2F5ZGFyYSBGQlgg')||poseRegistry.get(poseId)?.format==='fbx';const id=noAnim?undefined:objId;return<ModelEB fallback={fallback}>{isFBX?<FBXModel src={exists as string} objId={id}/>:<GLBModel src={exists as string} objId={id}/>}</ModelEB>;}
class ModelEB extends React.Component<{fallback:React.ReactNode;children:React.ReactNode},{err:boolean}>{constructor(p:{fallback:React.ReactNode;children:React.ReactNode}){super(p);this.state={err:false};}static getDerivedStateFromError(){return{err:true};}render(){return this.state.err?this.props.fallback:this.props.children;}}
function GLBModel({src,objId}:{src:string;objId?:string}){const{scene,animations}=useGLTF(src);const cloned=useMemo(()=>{const s=scene.clone(true);s.traverse(standardize);mergeGroupMeshes(s);normalizeScale(s);return s;},[scene]);const wrapped=useMemo(()=>{const g=new THREE.Group();const cc=cloned.clone(true);g.add(cc);addBoneOcta(g);return g;},[cloned]);useEffect(()=>{if(objId){const m=new THREE.AnimationMixer(cloned);if(animations.length>0){animations.forEach(c=>{const a=m.clipAction(c);a.setLoop(THREE.LoopRepeat,Infinity);a.play();a.paused=true;});}animMixers.set(objId,m);return()=>{animMixers.delete(objId);};}},[cloned,animations,objId]);return<primitive object={wrapped}/>;}
function FBXModel({src,objId}:{src:string;objId?:string}){const[scene,setScene]=useState<THREE.Group|null>(null);const[anims,setAnims]=useState<THREE.AnimationClip[]>([]);useEffect(()=>{let c=false;const loader=new FBXLoader();loader.load(src,(fbx:THREE.Group)=>{if(c)return;fbx.traverse(standardize);normalizeScale(fbx);addBoneOcta(fbx);setScene(fbx);const a=(fbx as any).animations||(loader as any).animations||[];setAnims(a);},undefined,()=>setScene(new THREE.Group()));return()=>{c=true;};},[src]);useEffect(()=>{if(scene&&objId){const m=new THREE.AnimationMixer(scene);if(anims.length>0){anims.forEach(c=>{const a=m.clipAction(c);a.setLoop(THREE.LoopRepeat,Infinity);a.play();a.paused=true;});}else{scene.traverse((ch:any)=>{if(ch.isSkinnedMesh){const dummy=new THREE.AnimationClip('dummy',1,[]);m.clipAction(dummy);}});}animMixers.set(objId,m);return()=>{animMixers.delete(objId);};}},[scene,anims,objId]);return scene?<primitive object={scene}/>:null;}
function addBoneOcta(root:THREE.Object3D){const sms:THREE.SkinnedMesh[]=[];root.traverse(c=>{if((c as any).isSkinnedMesh)sms.push(c as THREE.SkinnedMesh);});if(!sms.length)console.warn('[bone] No SkinnedMesh found in model');for(const sm of sms){if(!sm.skeleton?.bones.length){console.warn('[bone] SkinnedMesh has no skeleton');continue;}console.log('[bone] Found',sm.skeleton.bones.length,'bones');const helper=new THREE.SkeletonHelper(sm);helper.material.linewidth=2;(helper.material as any).depthTest=false;root.add(helper);const sk=sm.skeleton;const depths=new Map<THREE.Bone,number>();const walk=(b:THREE.Bone,d:number)=>{depths.set(b,d);b.children.forEach(c=>{if(c instanceof THREE.Bone)walk(c,d+1);});};walk(sk.bones[0],0);sk.bones.forEach(b=>{const depth=depths.get(b)||0;const t=Math.min(1,depth/8);const r=0.3+0.7*(1-t);const g=0.9-0.5*t;const bl=1-0.6*t;const childBone=b.children.find(c=>c instanceof THREE.Bone)as THREE.Bone|null;const size=0.06+0.02*(1-t);const sphere=new THREE.Mesh(new THREE.SphereGeometry(size,6,4),new THREE.MeshBasicMaterial({color:new THREE.Color(r,g,bl),depthTest:false,transparent:true,opacity:0.9}));b.add(sphere);if(childBone){const coneLen=0.12;const cone=new THREE.Mesh(new THREE.ConeGeometry(size*1.2,coneLen,5,2),new THREE.MeshBasicMaterial({color:new THREE.Color(r,g,bl),depthTest:false,transparent:true,opacity:0.7}));cone.position.copy(childBone.position).multiplyScalar(0.5);cone.lookAt(childBone.position);cone.rotateX(Math.PI/2);b.add(cone);}});}}
const SCALE_FACTOR=0.12;
function RotationGizmo({center,onRotate}:{center:Vec3;onRotate:(axis:0|1|2,dx:number,dy:number)=>void}){const{gl,camera}=useThree();const gRef=useRef<THREE.Group>(null);const drag=useRef<{axis:0|1|2;lastX:number;lastY:number}|null>(null);useFrame(()=>{if(!gRef.current)return;const d=camera.position.distanceTo(new THREE.Vector3(...center));gRef.current.scale.setScalar(d*SCALE_FACTOR);});const onDown=useCallback((axis:0|1|2)=>(e:any)=>{e.stopPropagation();if(drag.current)return;window.dispatchEvent(new CustomEvent('gizmo-drag-start'));drag.current={axis,lastX:e.clientX,lastY:e.clientY};(gl.domElement as any).style.cursor='grabbing';},[gl.domElement]);useEffect(()=>{const mv=(e:PointerEvent)=>{if(!drag.current)return;const dx=e.clientX-drag.current.lastX,dy=e.clientY-drag.current.lastY;drag.current.lastX=e.clientX;drag.current.lastY=e.clientY;onRotate(drag.current.axis,dx,dy);};const up=()=>{if(!drag.current)return;(gl.domElement as any).style.cursor='';window.dispatchEvent(new CustomEvent('gizmo-drag-end'));drag.current=null;};window.addEventListener('pointermove',mv);window.addEventListener('pointerup',up);return()=>{window.removeEventListener('pointermove',mv);window.removeEventListener('pointerup',up);};},[onRotate,gl.domElement]);const W=0.05;return(<group ref={gRef} position={center as[number,number,number]}><group onPointerDown={onDown(2)}><mesh><ringGeometry args={[1-W,1+W,32,1,0,Math.PI/2]}/><meshBasicMaterial color="#4488ff" transparent opacity={0.6} side={THREE.DoubleSide}/></mesh></group><group onPointerDown={onDown(1)} rotation={[Math.PI/2,0,0]}><mesh><ringGeometry args={[1-W,1+W,32,1,0,Math.PI/2]}/><meshBasicMaterial color="#ddbb00" transparent opacity={0.6} side={THREE.DoubleSide}/></mesh></group><group onPointerDown={onDown(0)} rotation={[0,-Math.PI/2,0]}><mesh><ringGeometry args={[1-W,1+W,32,1,0,Math.PI/2]}/><meshBasicMaterial color="#ff4444" transparent opacity={0.6} side={THREE.DoubleSide}/></mesh></group></group>);}
function CameraAxes({sel}:{sel:boolean}){return sel?<group>{[[1,0,0,'#ff3333'],[0,1,0,'#44dd44'],[0,0,1,'#4488ff']].map(([ax,ay,az,clr])=>(<group key={clr as string}>{/* + thick */}<mesh position={[(ax as number)*0.7,(ay as number)*0.7,(az as number)*0.7]} rotation={ax?[0,0,Math.PI/2]:az?[Math.PI/2,0,0]:[0,0,0]}><cylinderGeometry args={[0.04,0.04,1.2,8]}/><meshBasicMaterial color={clr as string}/></mesh>{/* - thin */}<mesh position={[-(ax as number)*0.35,-(ay as number)*0.35,-(az as number)*0.35]} rotation={ax?[0,0,Math.PI/2]:az?[Math.PI/2,0,0]:[0,0,0]}><cylinderGeometry args={[0.012,0.012,0.7,6]}/><meshBasicMaterial color={clr as string}/></mesh></group>))}</group>:null;}
function CameraGLB({pos,tgt}:{pos:Vec3;tgt:Vec3}){const{scene}=useGLTF('/models/IMAXX%20%E6%91%84%E5%83%8F%E6%9C%BA.glb');const cloned=useMemo(()=>{const c=scene.clone(true);c.rotation.set(0,Math.PI-13*Math.PI/180,0);c.traverse((ch:any)=>{if(ch.isMesh){ch.castShadow=true;if(ch.material){ch.material.roughness=0.5;ch.material.metalness=0;ch.material.emissive=ch.material.emissive||new THREE.Color('#444');ch.material.emissiveIntensity=0.3;}}});return c;},[scene]);return<primitive object={cloned} position={[0,0.2,0]} lookAt={tgt} scale={1.5}/>;}
function FallbackCamera({pos,tgt}:{pos:Vec3;tgt:Vec3}){return<group position={pos as[number,number,number]}><mesh lookAt={tgt}><boxGeometry args={[0.45,0.28,0.4]}/><meshStandardMaterial color="#3a3a44" roughness={0.5}/></mesh><mesh lookAt={tgt} position={[0,-0.04,0.22]}><boxGeometry args={[0.38,0.16,0.2]}/><meshStandardMaterial color="#f44" emissive="#f22" emissiveIntensity={0.6}/></mesh><mesh lookAt={tgt} position={[0,0,0.28]}><cylinderGeometry args={[0.09,0.07,0.16,12]}/><meshStandardMaterial color="#555" roughness={0.3}/></mesh></group>;}
