const _p:Vec3=[0,0,0];const _r:Vec3=[0,0,0];const _s:Vec3=[1,1,1];const _f:Vec3=[0,0,0];const _fv=new THREE.Vector3();let _mt=0;const mover=(el:THREE.Object3D,obj:SceneObject)=>{const now=performance.now();if(now-_mt<200)return;_mt=now;_p[0]=el.position.x;_p[1]=el.position.y;_p[2]=el.position.z;_r[0]=el.rotation.x;_r[1]=el.rotation.y;_r[2]=el.rotation.z;_s[0]=el.scale.x;_s[1]=el.scale.y;_s[2]=el.scale.z;_fv.set(0,0,-1);el.localToWorld(_fv);_f[0]=_fv.x;_f[1]=_fv.y;_f[2]=_fv.z;(window as any).__dragObj={el};window.dispatchEvent(new CustomEvent('scene3d-object-moved',{detail:{id:obj.id,position:_p,rotation:_r,scale:_s,forward:_f,objRef:el}}));};
function TileGround(){const{scene}=useThree();const meshRef=useRef<THREE.InstancedMesh>(null);const geom=useMemo(()=>{const shape=new THREE.Shape();const s=0.49;shape.moveTo(-s,-s);shape.lineTo(s,-s);shape.lineTo(s,s);shape.lineTo(-s,s);shape.closePath();const eg=new THREE.ExtrudeGeometry(shape,{depth:0.12,bevelEnabled:true,bevelThickness:0.03,bevelSize:0.03,bevelSegments:2});eg.rotateX(-Math.PI/2);eg.translate(0,-0.06,0);return eg;},[]);useEffect(()=>{if(!meshRef.current)return;const m=meshRef.current;const dummy=new THREE.Object3D();const half=30;let idx=0;for(let x=-half;x<half;x++){for(let z=-half;z<half;z++){dummy.position.set(x+0.5,-0.06,z+0.5);dummy.updateMatrix();m.setMatrixAt(idx++,dummy.matrix);}}m.instanceMatrix.needsUpdate=true;},[]);return<instancedMesh ref={meshRef} args={[geom,undefined,3600]} receiveShadow frustumCulled={false}><meshStandardMaterial color="#c0c0c0" roughness={0.35} metalness={0.02}/></instancedMesh>;}
