function ProcSky({sunAzimuth,sunElevation}:{sunAzimuth:number;sunElevation:number}){const az=sunAzimuth||45;const el=sunElevation||40;const sunDir=useMemo(()=>{const phi=THREE.MathUtils.degToRad(90-el);const theta=THREE.MathUtils.degToRad(az);return new THREE.Vector3().setFromSphericalCoords(1,phi,theta);},[az,el]);const skyMesh=useMemo(()=>{const geo=new THREE.SphereGeometry(55,64,32);const mat=new THREE.ShaderMaterial({uniforms:{uSunDir:{value:sunDir.clone()}},vertexShader:`varying vec3 vWorldPos;void main(){vec4 wp=modelMatrix*vec4(position,1.0);vWorldPos=wp.xyz;gl_Position=projectionMatrix*modelViewMatrix*vec4(position,1.0);}`,fragmentShader:`varying vec3 vWorldPos;uniform vec3 uSunDir;void main(){vec3 dir=normalize(vWorldPos);float h=dir.y;float t=smoothstep(-0.05,0.35,h);vec3 zenith=vec3(0.35,0.62,0.98);vec3 horizon=vec3(0.72,0.90,1.0);vec3 col=mix(horizon,zenith,t)*1.3;float sunDot=clamp(dot(dir,uSunDir),0.0,1.0);float glow=pow(sunDot,80.0)*0.25;gl_FragColor=vec4(col+glow*vec3(1.0,0.9,0.7),1.0);}`,side:THREE.BackSide,depthWrite:false});const m=new THREE.Mesh(geo,mat);m.renderOrder=-1;m.frustumCulled=false;return m;},[]);useEffect(()=>{skyMesh.material.uniforms.uSunDir.value.copy(sunDir);},[sunDir,skyMesh]);return<primitive object={skyMesh}/>;}
